from pathlib import Path
from html import escape
from format_lecon import paras
D=Path(__file__).resolve().parents[1]
def quote(n,starts):
 lines=(D/f'evidence/AIPS_{n}.txt').read_text().splitlines();out=[]
 for s in starts:
  hits=[x for x in lines if x.startswith(s)];assert len(hits)==1,(n,s,len(hits));out.append('<p>« '+escape(hits[0])+' »</p>')
 return '<blockquote>'+'\n'.join(out)+'</blockquote>'
def cycloplegie(l):
 d=paras('Cyclogyl est un collyre diagnostique au cyclopentolate, antimuscarinique. La mydriase dilate la pupille ; la cycloplégie bloque l’accommodation. Une pupille large ne prouve pas à elle seule une cycloplégie suffisante. La notice suisse de mai 2021, autorisation 32634, prime sur les schémas étrangers.')
 d+=quote('32634',["Instiller 1 ou 2 gouttes de Cyclogyl 0,5% ou 1,0%", "Instiller 1 ou 2 gouttes de Cyclogyl 0,5% ou 1%", "Instiller 1 goutte de Cyclogyl 0,5%", "Hypersensibilité connue", "Cyclogyl est utilisé exclusivement", "Cyclogyl ne doit pas être utilisé chez les enfants de moins", "Une sensibilité augmentée", "Le risque potentiel pour l'être humain", "Il n'est pas connu si le principe actif"])
 d+=paras('Les deux premiers paragraphes de dose concernent respectivement l’adulte, puis l’enfant et l’adolescent. Le troisième concerne les jeunes enfants autorisés par la notice ; il ne lève jamais l’interdiction avant un an. La notice ne définit pas de frontière numérique supplémentaire pour le terme jeune enfant : ne pas en inventer.', 'Vérifier angle iridocornéen, antécédents de réaction anticholinergique, épilepsie, fièvre et médicaments associés. Les antihistaminiques antimuscariniques, phénothiazines et antidépresseurs tricycliques peuvent renforcer l’effet. En cas d’agitation, confusion, convulsions, fièvre ou trouble cardiorespiratoire, arrêter les instillations et obtenir une prise en charge urgente.', 'La notice ne propose pas d’ajustement chiffré rénal ou hépatique. Ne pas en déduire une sécurité démontrée. Protéger de l’éblouissement et ne pas conduire tant que la vision ou la vigilance sont altérées. Le délai moyen de dilatation d’une brochure ne remplace pas cette règle individuelle.', 'Le guide britannique de 2012 décrit une utilisation avant six mois ; ce schéma n’est pas transposé ici. Chez le nourrisson, l’ophtalmologue choisit une stratégie diagnostique appropriée et surveillée, sans retarder l’exclusion d’une cause organique.')
 return l.subwindow('cyclogyl','Cycloplégie : Cyclogyl et sécurité suisse',d,(7,3))
def atropine(l):
 d=paras('Atropine SDU Faure est un collyre en doses unitaires à 5 mg/ml, soit 0,5 %. La notice porte le numéro d’autorisation 46994 ; 46994035 est l’identifiant documentaire du fichier. Il ne s’agit pas d’une solution injectable. L’antimuscarinique réduit l’accommodation de l’œil fixateur dans une pénalisation prescrite par le spécialiste.')
 d+=quote('46994035',["Pour paralyser l'accommodation", "Instiller 1 goutte 1 à 3 fois", "Les enfants et les petits enfants seront traités", "Glaucome et glaucome", "Hypersensibilité à l'atropine", "L'atropine doit être utilisée", "L'effet de l'atropine peut être renforcé", "Des malformations", "Interrompre l'allaitement", "Les patients doivent être rendus attentifs"])
 d+=paras('La posologie générale de la notice ne définit pas un programme universel de pénalisation : œil traité, fréquence, durée et contrôles sont individualisés. Ne pas recopier un schéma étranger au week-end ou une concentration différente en le présentant comme une dose de cette notice.', 'La surveillance compare l’acuité des deux yeux et vérifie que l’œil pénalisé ne développe pas à son tour une baisse de vision. Prévenir l’entourage des signes anticholinergiques : bouche sèche, rougeur, fièvre, agitation, accélération du pouls ou difficulté à uriner. Une suspicion d’intoxication impose l’arrêt et un avis urgent.', 'Un eczéma palpébral conduit à réévaluer et remplacer le produit selon le prescripteur. La durée des effets oculaires peut être prolongée ; l’arrêt ne rend pas immédiatement la conduite sûre. Aucun palier posologique rénal ou hépatique n’est fourni dans cette notice.', 'Les mesures optiques et l’occlusion restent des alternatives selon le type d’amblyopie et la tolérance. La pénalisation traite le développement visuel ; elle ne remplace ni le bilan de la cause ni, lorsqu’elle est indiquée, la chirurgie d’alignement.')
 return l.subwindow('atropine','Atropine : pénalisation et précautions',d,(8,6))
